fn to_str(n: Int) -> Str {
    if n < 10 {
        concat(int_to_str(n), "")
    } else {
        let last_digit = n % 10
        let rest = n / 10
        let rest_str = to_str(rest)
        concat(rest_str, int_to_str(last_digit))
    }
}

